      { q: "May any squadron patch be placed on an OCP uniform?", options: ["Yes, every squadron patch is automatically authorized", "No; verify the patch is currently approved and authorized", "Only if it is colorful", "Only cadet officers may wear one"], answer: 1, why: "Current OCP guidance limits patches and requires applicable approval." },
      { q: "What should you do when an exact insignia measurement is uncertain?", options: ["Estimate", "Copy a friend", "Use the current CAPR 39-1 figure or table and ask staff", "Leave every insignia off"], answer: 2, why: "Exact placement should be verified from the current official illustration or text." }
